//! Rust-side conformance test for the GGL -> symthaea-canvas adapter.
//!
//! The fixture is generated by the Python reference adapter, then consumed by
//! the actual Canvas serde types and renderer. This checks the public Rust
//! contract; it does not claim the Python adapter is the production compiler.

use serde_json::Value;
use symthaea_canvas::render_svg;
use symthaea_canvas::scene_graph::{NodeKind, SceneNode};

const GGL_SOURCE: &str = include_str!("fixtures/ggl-source.json");
const CANVAS_SCENE: &str = include_str!("fixtures/canvas-scene.json");
const IDENTITY_MAP: &str = include_str!("fixtures/identity-map.json");
const ADAPTER_MANIFEST: &str = include_str!("fixtures/adapter-manifest.json");
const GEOMETRY_REL_TOLERANCE: f64 = 1.0e-5;

fn assert_close(actual: f32, expected: f64, label: &str) {
    let actual = f64::from(actual);
    let tolerance = GEOMETRY_REL_TOLERANCE * expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tolerance,
        "{label}: actual={actual}, expected={expected}, tolerance={tolerance}"
    );
}

fn expect_group_id(node: &SceneNode) -> &str {
    match &node.kind {
        NodeKind::Group { id: Some(id) } => id,
        other => panic!("expected identity wrapper Group, got {other:?}"),
    }
}

#[test]
fn ggl_fixture_deserializes_and_renders_through_canvas() {
    let source: Value = serde_json::from_str(GGL_SOURCE).expect("valid GGL source fixture");
    let identity: Value = serde_json::from_str(IDENTITY_MAP).expect("valid identity fixture");
    let manifest: Value = serde_json::from_str(ADAPTER_MANIFEST).expect("valid manifest fixture");
    let canvas: SceneNode =
        serde_json::from_str(CANVAS_SCENE).expect("Canvas SceneNode serde contract must accept adapter output");

    let primitives = source["primitives"].as_array().expect("source primitives");
    let entries = identity["entries"].as_array().expect("identity entries");
    assert_eq!(primitives.len(), 4, "fixture covers four supported primitive types");
    assert_eq!(entries.len(), primitives.len());
    assert_eq!(canvas.children.len(), primitives.len());
    assert_eq!(manifest["primitive_count"].as_u64(), Some(primitives.len() as u64));
    assert_eq!(manifest["units"].as_str(), source["units"].as_str());
    assert_eq!(manifest["source_sha256"].as_str(), source["source_sha256"].as_str());
    assert_eq!(manifest["program_sha256"].as_str(), source["program_sha256"].as_str());
    assert_eq!(manifest["geometry_sha256"].as_str(), source["geometry_sha256"].as_str());
    assert_eq!(identity["canvas_scene_digest"], manifest["canvas_scene_digest"]);
    assert_eq!(identity["namespace"], manifest["namespace"]);

    let mut seen_ids = std::collections::BTreeSet::new();
    let mut rendered_ids = Vec::with_capacity(entries.len());

    for (index, ((primitive, entry), wrapper)) in primitives
        .iter()
        .zip(entries.iter())
        .zip(canvas.children.iter())
        .enumerate()
    {
        let semantic_id = primitive["id"].as_str().expect("semantic ID");
        let wrapper_id = expect_group_id(wrapper);
        assert_eq!(entry["semantic_id"].as_str(), Some(semantic_id));
        assert_eq!(entry["canvas_group_id"].as_str(), Some(wrapper_id));
        assert!(seen_ids.insert(wrapper_id.to_owned()), "duplicate wrapper ID: {wrapper_id}");
        assert_eq!(wrapper.children.len(), 1, "wrapper {index} must contain exactly one primitive");
        let leaf = &wrapper.children[0];

        match primitive["type"].as_str().expect("primitive type") {
            "circle" => match &leaf.kind {
                NodeKind::Circle { cx, cy, r } => {
                    assert_close(*cx, primitive["cx"].as_f64().unwrap(), "circle.cx");
                    assert_close(*cy, -primitive["cy"].as_f64().unwrap(), "circle.cy (y-up to y-down)");
                    assert_close(*r, primitive["radius"].as_f64().unwrap(), "circle.radius");
                }
                other => panic!("circle mapped to unexpected Canvas kind: {other:?}"),
            },
            "segment" => match &leaf.kind {
                NodeKind::Line { x1, y1, x2, y2 } => {
                    assert_close(*x1, primitive["x1"].as_f64().unwrap(), "segment.x1");
                    assert_close(*y1, -primitive["y1"].as_f64().unwrap(), "segment.y1");
                    assert_close(*x2, primitive["x2"].as_f64().unwrap(), "segment.x2");
                    assert_close(*y2, -primitive["y2"].as_f64().unwrap(), "segment.y2");
                }
                other => panic!("segment mapped to unexpected Canvas kind: {other:?}"),
            },
            "polygon" => match &leaf.kind {
                NodeKind::Polygon { points, closed } => {
                    assert!(*closed, "GGL polygon must remain closed");
                    let vertices = primitive["vertices"].as_array().expect("polygon vertices");
                    assert_eq!(points.len(), vertices.len());
                    for (vertex_index, (actual, expected)) in points.iter().zip(vertices.iter()).enumerate() {
                        assert_close(actual.0, expected[0].as_f64().unwrap(), "polygon.x");
                        assert_close(actual.1, -expected[1].as_f64().unwrap(), "polygon.y");
                        assert!(actual.0.is_finite() && actual.1.is_finite(), "vertex {vertex_index} must be finite");
                    }
                }
                other => panic!("polygon mapped to unexpected Canvas kind: {other:?}"),
            },
            "arc" => match &leaf.kind {
                NodeKind::Path { d } => {
                    assert!(d.starts_with("M "), "arc path must have a move-to command");
                    assert_eq!(d.matches(" A ").count(), 1, "arc fixture must contain one SVG arc command");
                    assert!(d.contains("A 3 3 0 0 0"), "positive GGL sweep must reverse after y-axis reflection");
                }
                other => panic!("arc mapped to unexpected Canvas kind: {other:?}"),
            },
            unsupported => panic!("fixture contains unrecognized primitive type {unsupported}"),
        }
        rendered_ids.push(wrapper_id.to_owned());
    }

    let svg = render_svg(&canvas, 0.5);
    assert!(svg.starts_with("<svg"));
    assert!(svg.ends_with("</svg>\n"));
    for id in rendered_ids {
        let needle = format!(r#"id="{id}""#);
        assert_eq!(svg.matches(&needle).count(), 1, "renderer must preserve wrapper ID exactly once: {id}");
    }
    assert!(!svg.contains("NaN"));
    assert!(!svg.contains("inf"));
}
